pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        // Deploy C with a non-zero staking token address and distributor address;
        // the constructor calls _transferOwnership(_msgSender()), making the deployer the owner.
        c = new C(address(this), address(this));
    }
    function testFuzz_property(address deployer) public {
        // The reference contract stores the deployer as owner; the buggy returns address(0).
        // We fuzz the deployer address. We assume deployer is not address(0) because
        // Ownable's constructor transfers ownership to the deployer (_msgSender()).
        vm.assume(deployer != address(0));

        // Deploy a fresh C from the given fuzzed deployer.
        vm.prank(deployer);
        C c2 = new C(address(this), address(this));

        // The property: owner() must return the deployer (non-zero).
        assertEq(c2.owner(), deployer);
    }
}

