pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(address intermediary, address /* unused */) public {
        // 1. the original owner is set to address(this) via setUp -> Ownable constructor.
        //    we wrap the call to owner() through a helper that will be the immediate msg.sender.
        // 2. deploy a minimal proxy that simply forwards a staticcall to c.owner() and returns the result.
        Proxy proxy = new Proxy();
        // 3. call owner() through the proxy; the correct contract returns address(this),
        //    the buggy one returns tx.origin which will be the proxy's address.
        address result = proxy.ownerOf(c);
        // 4. assertion: owner must still equal the address that ownable stored, i.e., address(this).
        assertTrue(result == address(this));
    }
}

contract Proxy {
    function ownerOf(C target) external view returns (address) {
        return target.owner();
    }
}

