pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address intermediary) public {
        // Assumption: the intermediary must not be the address of c itself or the test contract
        vm.assume(intermediary != address(this) && intermediary != address(c));
        // Deploy a minimal forwarder that calls owner() on c
        Forwarder forwarder = new Forwarder(c);
        // The forwarder calls owner()
        address returnedOwner = forwarder.queryOwner();
        // The real owner is set during construction (it is address(this))
        address realOwner = c.owner();
        // The returned owner must equal the real owner
        assertTrue(returnedOwner == realOwner);
    }
}

contract Forwarder {
    C c;
    constructor(C _c) { c = _c; }
    function queryOwner() external view returns (address) {
        return c.owner();
    }
}

