pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address fuzzedCoinbase) public {
        // The bug makes owner() return block.coinbase instead of the true owner set at construction.
        // We verify that for any coinbase, the returned owner matches the actual Ownable storage owner.
        // The reference satisfies: owner() == initialOwner (always).
        // The bug breaks when block.coinbase != initialOwner.

        // Capture the true owner (set in setUp as address(this)).
        address trueOwner = address(this);

        // We need to set block.coinbase to a fuzzed value to expose the bug.
        // vm.coinbase is a cheatcode that sets block.coinbase for the test environment.
        vm.coinbase(fuzzedCoinbase);

        // The property: owner() must always return the true owner that Ownable stores.
        // Assert that the view function returns the true owner address.
        assertTrue(c.owner() == trueOwner);
    }
}

