        // The invariant: owner must never be the zero address after any transferOwnership call.
        // The reference contract reverts on newOwner == address(0), so this assertion always holds.
        // The buggy contract allows it, so the fuzzer will find newOwner == address(0) that makes this false.
        assertTrue(c.owner() != address(0));
    }
}
